Key Description Type type Fixed string identifying the report type <code>"WholeSlideDifferential"</code> points Cells or objects found by the model array of objects <code>{x: number, y: number, score: number, type: string}</code> scores Map of score names to score values map from string to number positivity_threshold Threshold for a given point to be considered positive number <pre><code>{
  "scanResults": [
    {
      "scanId": "8946136",
      "workflow": {
        "key": "Proliferation Score",
        "model_name": "KI67 Breast-4R",
        "provider": "Mindpeak",
        "ruo": true,
        "report": {
          "type": "WholeSlideDifferential",
          "positivity_threshold": 0.4376593987751759,
          "scores": {
            "proliferation_score": 0.13330553429026412
          },
          "points": [
            { "x": 13042, "y": 41972, "score": 0.32819, "type": "tumor" },
            { "x": 13030, "y": 41884, "score": 0.33399, "type": "tumor" },
            { "x": 11938, "y": 41282, "score": 0.63977, "type": "tumor" }
          ]
        }
      }
    }
  ]
}
</code></pre>

